    /**
     * Gets an array of ServicioReceptor objects which contain a foreign key that references this object.
     *
     * If the $criteria is not null, it is used to always fetch the results from the database.
     * Otherwise the results are fetched from the database the first time, then cached.
     * Next time the same method is called without $criteria, the cached collection is returned.
     * If this TipoServicio is new, it will return
     * an empty collection or the current collection; the criteria is ignored on a new object.
     *
     * @param Criteria $criteria optional Criteria object to narrow the query
     * @param PropelPDO $con optional connection object
     * @return PropelObjectCollection|ServicioReceptor[] List of ServicioReceptor objects
     * @throws PropelException
     */
    public function getServicioReceptors($criteria = null, PropelPDO $con = null)
    {
        $partial = $this->collServicioReceptorsPartial && !$this->isNew();
        if (null === $this->collServicioReceptors || null !== $criteria  || $partial) {
            if ($this->isNew() && null === $this->collServicioReceptors) {
                // return empty collection
                $this->initServicioReceptors();
            } else {
                $collServicioReceptors = ServicioReceptorQuery::create(null, $criteria)
                    ->filterByTipoServicio($this)
                    ->find($con);
                if (null !== $criteria) {
                    if (false !== $this->collServicioReceptorsPartial && count($collServicioReceptors)) {
                      $this->initServicioReceptors(false);

                      foreach ($collServicioReceptors as $obj) {
                        if (false == $this->collServicioReceptors->contains($obj)) {
                          $this->collServicioReceptors->append($obj);
                        }
                      }

                      $this->collServicioReceptorsPartial = true;
                    }

                    $collServicioReceptors->getInternalIterator()->rewind();

                    return $collServicioReceptors;
                }

                if ($partial && $this->collServicioReceptors) {
                    foreach ($this->collServicioReceptors as $obj) {
                        if ($obj->isNew()) {
                            $collServicioReceptors[] = $obj;
                        }
                    }
                }

                $this->collServicioReceptors = $collServicioReceptors;
                $this->collServicioReceptorsPartial = false;
            }
        }

        return $this->collServicioReceptors;
    }

    /**
     * Sets a collection of ServicioReceptor objects related by a one-to-many relationship
     * to the current object.
     * It will also schedule objects for deletion based on a diff between old objects (aka persisted)
     * and new objects from the given Propel collection.
     *
     * @param PropelCollection $servicioReceptors A Propel collection.
     * @param PropelPDO $con Optional connection object
     * @return TipoServicio The current object (for fluent API support)
     */
    public function setServicioReceptors(PropelCollection $servicioReceptors, PropelPDO $con = null)
    {
        $servicioReceptorsToDelete = $this->getServicioReceptors(new Criteria(), $con)->diff($servicioReceptors);


        $this->servicioReceptorsScheduledForDeletion = $servicioReceptorsToDelete;

        foreach ($servicioReceptorsToDelete as $servicioReceptorRemoved) {
            $servicioReceptorRemoved->setTipoServicio(null);
        }

        $this->collServicioReceptors = null;
        foreach ($servicioReceptors as $servicioReceptor) {
            $this->addServicioReceptor($servicioReceptor);
        }

        $this->collServicioReceptors = $servicioReceptors;
        $this->collServicioReceptorsPartial = false;

        return $this;
    }

    /**
     * Returns the number of related ServicioReceptor objects.
     *
     * @param Criteria $criteria
     * @param boolean $distinct
     * @param PropelPDO $con
     * @return int             Count of related ServicioReceptor objects.
     * @throws PropelException
     */
    public function countServicioReceptors(Criteria $criteria = null, $distinct = false, PropelPDO $con = null)
    {
        $partial = $this->collServicioReceptorsPartial && !$this->isNew();
        if (null === $this->collServicioReceptors || null !== $criteria || $partial) {
            if ($this->isNew() && null === $this->collServicioReceptors) {
                return 0;
            }

            if ($partial && !$criteria) {
                return count($this->getServicioReceptors());
            }
            $query = ServicioReceptorQuery::create(null, $criteria);
            if ($distinct) {
                $query->distinct();
            }

            return $query
                ->filterByTipoServicio($this)
                ->count($con);
        }

        return count($this->collServicioReceptors);
    }

    /**
     * Method called to associate a ServicioReceptor object to this object
     * through the ServicioReceptor foreign key attribute.
     *
     * @param    ServicioReceptor $l ServicioReceptor
     * @return TipoServicio The current object (for fluent API support)
     */
    public function addServicioReceptor(ServicioReceptor $l)
    {
        if ($this->collServicioReceptors === null) {
            $this->initServicioReceptors();
            $this->collServicioReceptorsPartial = true;
        }

        if (!in_array($l, $this->collServicioReceptors->getArrayCopy(), true)) { // only add it if the **same** object is not already associated
            $this->doAddServicioReceptor($l);

            if ($this->servicioReceptorsScheduledForDeletion and $this->servicioReceptorsScheduledForDeletion->contains($l)) {
                $this->servicioReceptorsScheduledForDeletion->remove($this->servicioReceptorsScheduledForDeletion->search($l));
            }
        }

        return $this;
    }

    /**
     * @param	ServicioReceptor $servicioReceptor The servicioReceptor object to add.
     */
    protected function doAddServicioReceptor($servicioReceptor)
    {
        $this->collServicioReceptors[]= $servicioReceptor;
        $servicioReceptor->setTipoServicio($this);
    }

    /**
     * @param	ServicioReceptor $servicioReceptor The servicioReceptor object to remove.
     * @return TipoServicio The current object (for fluent API support)
     */
    public function removeServicioReceptor($servicioReceptor)
    {
        if ($this->getServicioReceptors()->contains($servicioReceptor)) {
            $this->collServicioReceptors->remove($this->collServicioReceptors->search($servicioReceptor));
            if (null === $this->servicioReceptorsScheduledForDeletion) {
                $this->servicioReceptorsScheduledForDeletion = clone $this->collServicioReceptors;
                $this->servicioReceptorsScheduledForDeletion->clear();
            }
            $this->servicioReceptorsScheduledForDeletion[]= clone $servicioReceptor;
            $servicioReceptor->setTipoServicio(null);
        }

        return $this;
    }


